package org.kanger;
import java.util.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextUniversalGroupedLocalRounds.Certificate;
import org.kanger.ContextUniversalSignedUnitExchange.*;
import org.kanger.ContextWitnessResultTransport.*;

/** Same complete deep continuation: original throwing rebase versus explicit owned session. */
public final class ContextUniversalSymbolicRebaseBudgetRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    public static void main(String[] args){try {
        System.setProperty("user.home",java.nio.file.Files.createTempDirectory("symbolic-rebase-budget-").toString());Snapshot x=ContextUniversalGroupedRoundsRunner.bind(true,"!anchor(1); !@u p(u);"),a=ContextUniversalGroupedRoundsRunner.bind(false,"!@u (p(u)&&b(u)->r(u))&&(p(u)&&r(u)->s(u));"),b=ContextUniversalGroupedRoundsRunner.bind(false,"!b(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);List<Snapshot> supplied=Arrays.asList(a,b);ContextUniversalCompoundExchange.Exchange input=ContextUniversalGroupedRoundsRunner.exchange(x,supplied,p,Collections.emptyMap());ContextUniversalGroupedRounds.SessionRun run=ContextUniversalGroupedRounds.runWithValidationReuse(x,supplied,p,Collections.emptyMap(),ContextUniversalGroupedRoundsRunner.units(input),input,ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);ContextUniversalGroupedRounds.Result stable=run.result;require(stable.status==ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&stable.completedRounds==3,stable.phase+": "+stable.reason);
        Map<Cut,Result> donors=new LinkedHashMap<>();Map<Cut,Certificate> certificates=new LinkedHashMap<>();List<Snapshot> receivers=new ArrayList<>();receivers.add(null);receivers.addAll(supplied);
        for(Snapshot receiver:receivers){Result base=ContextUniversalFrozenConstraints.closeSignedCompounds(ContextUniversalCompoundExchangeRunner.rows(x,receiver),stable.output.packet,null,stable.symbolicOutput,stable.compoundOutput,16,16,512,256,WORK);require(base.closed,base.reason);ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.runWithValidationReuse(base,ContextUniversalGroupedRoundsRunner.local(),4096);require(local.stable,local.reason);Cut cut=receiver==null?Cut.of(x):Cut.of(receiver);donors.put(cut,local.output.output);certificates.put(cut,local.output);}
        List<Cut> cuts=new ArrayList<>(donors.keySet());Map<Cut,ConstraintTransfer> transfers=new LinkedHashMap<>();for(Cut cut:cuts){ConstraintTransfer t=ContextWitnessResultTransport.transferConstraintsCertifiedWithValidationReuse(certificates.get(cut),16,WORK,4096).transfer;require(t.transferred,t.reason);ContextUniversalSignedProductAudit.Result audit=ContextUniversalSignedProductAudit.bindWithValidationReuse(donors.get(cut),t,65536,WORK,4096).result;require(audit.bound,audit.reason);transfers.put(cut,t);}
        ContextUniversalSignedUnitExchange.Collection units=ContextUniversalSignedUnitExchange.collectWithValidationReuse(x,stable.output.packet,cuts,donors,512,256,16,WORK,4096).collection;require(units.collected,units.reason);ContextUniversalCompoundExchange.Collection compounds=ContextUniversalCompoundExchange.collectWithValidationReuse(x,stable.output.packet,cuts,donors,512,256,16,WORK,4096).collection;require(compounds.collected,compounds.reason);ConstraintBarrier barrier=ContextWitnessResultTransport.mergeConstraints(ContextWitnessResultTransport.family(stable.output.packet,cuts,WORK),transfers,WORK);require(barrier.merged,barrier.reason);
        boolean refused=false;try{ContextUniversalSignedUnitExchange.rebase(units.output,barrier,WORK);}catch(IllegalStateException e){refused=e.getMessage().contains("Ground transport work limit");}require(refused,"original rebase throws at SAME64m; no successful prefix");
        SessionRebase fresh=ContextUniversalSignedUnitExchange.rebaseWithValidationReuse(units.output,barrier,WORK,4096);Exchange e=fresh.exchange;require(fresh.metrics.work<WORK&&fresh.metrics.hits>0&&fresh.metrics.entries==0,"new owned scope closes at unchanged budget");require(e.prior==units.output&&e.barrier==barrier&&e.common==barrier.packet&&e.x==x&&e.checks==units.output.checks&&e.units==units.output.units,"actual prior/barrier/common/checks/unit inventory preserved by reference");require(ContextUniversalSignedUnitExchange.sameContents(e,stable.symbolicOutput,WORK),"exact carried symbolic Source-depth minima");
        System.out.println("SYMBOLIC_REBASE_RETAINED legacyRefused=true sessionWork="+fresh.metrics.work+" hits="+fresh.metrics.hits+" verified="+fresh.metrics.verified+" peak="+fresh.metrics.peakEntries+" units="+e.units.size());System.out.println("CONTEXT_UNIVERSAL_SYMBOLIC_REBASE_BUDGET_PASS checks="+checks);System.exit(0);
    }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
